using Pragmatic.SourceGen;
using Pragmatic.SourceGenerator.Core;
using Pragmatic.SourceGenerator.Features.Persistence.Models;
using Pragmatic.SourceGenerator.Features.Persistence.Templates;

namespace Pragmatic.SourceGenerator.Features.Traits;

/// <summary>
///     EF Core's repository of a trait's child (#888): the comment, the note, the attachment and the shared tag.
/// </summary>
/// <remarks>
///     <para>
///         A trait's child is generated by this generator, so it never reaches Persistence's entity provider, and EF Core registered no
///         repository for it while both engines do. It is the same repository every entity has, from the same template, inside the same filters
///         (the child's <c>ParentVisibilityFilter</c> included, which the boundary's query-filter registration already registers), keyed on the
///         boundary like the rest.
///     </para>
///     <para>
///         Without the bulk writes: the model is built from the trait, not from the entity's symbol, so it has no columns to write. The tag
///         link has no repository: it is keyed on its two foreign keys and is not an <c>IEntity</c> on EF Core.
///     </para>
///     <para>The host registers it from the trait metadata's <c>repositoryType</c>, as it registers every other entity's from Persistence's.</para>
/// </remarks>
internal static class TraitRepositories
{
    /// <summary>The repository's type name, as the trait metadata declares it to the host.</summary>
    public static string RepositoryTypeOf(string fullTypeName) => $"{fullTypeName}.Repository";

    /// <summary>The child's repository, nested in its partial class.</summary>
    public static Artifact Repository(
        string typeName,
        string ns,
        string? boundaryFullTypeName,
        string? boundaryName,
        bool isSoftDelete,
        EfCoreProvider provider,
        string trigger)
    {
        var model = new EntityMetadataModel
        {
            TypeName = typeName,
            FullTypeName = string.IsNullOrEmpty(ns) ? typeName : $"{ns}.{typeName}",
            Namespace = ns,
            IdType = "Guid",
            Accessibility = "public",
            IsValid = true,
            IsFromReference = false,
            BoundaryTypeFullName = boundaryFullTypeName,
            BoundaryName = boundaryName,
            IsSoftDelete = isSoftDelete,
        };

        // Keyed on Id: the child's configuration maps Id and ignores PersistenceId, its alias (AttachmentEntityConfigTemplate and the rest).
        return new RepositoryTemplate(model, provider, bulk: false, trigger: trigger, key: "Id").RenderOutput();
    }
}
